        f.debug_struct("IntoService").finish_non_exhaustive()
    }
}

impl<H, T, S, B> Clone for HandlerService<H, T, S, B>
where
    H: Clone,
    S: Clone,
{
    fn clone(&self) -> Self {
        Self {
            handler: self.handler.clone(),
            state: self.state.clone(),
            _marker: PhantomData,
        }
    }
}

impl<H, T, S, B> Service<Request<B>> for HandlerService<H, T, S, B>
where
    H: Handler<T, S, B> + Clone + Send + 'static,
    B: Send + 'static,
    S: Clone + Send + Sync,
{
    type Response = Response;
    type Error = Infallible;
    type Future = super::future::IntoServiceFuture<H::Future>;

    #[inline]
    fn poll_ready(&mut self, _cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        super::handler_service_poll_ready()
    }

    fn call(&mut self, req: Request<B>) -> Self::Future {
        super::call_handler_with_state(self.handler.clone(), req, self.state.clone())
    }
}

