cd /data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-2s81brkv/testbed && mkdir -p axum/tests && cat > axum/tests/tmp_fallback_state.rs <<'EOF'
use axum::{
    extract::State,
    http::StatusCode,
    routing::get,
    Router,
};

#[tokio::test]
async fn fallback_method_router_with_state() {
    async fn fallback(State(state): State<&'static str>) -> &'static str {
        state
    }

    async fn not_found() -> StatusCode {
        StatusCode::NOT_FOUND
    }

    let app = Router::new()
        .fallback(get(fallback).fallback(not_found))
        .with_state("state");

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move {
        axum::Server::from_tcp(listener.into_std().unwrap())
            .unwrap()
            .serve(app.into_make_service())
            .await
            .unwrap();
    });

    let res = reqwest::get(format!("http://{addr}/does-not-exist")).await.unwrap();
    assert_eq!(res.status(), StatusCode::OK);
    assert_eq!(res.text().await.unwrap(), "state");

    let client = reqwest::Client::new();
    let res = client
        .post(format!("http://{addr}/does-not-exist"))
        .send()
        .await
        .unwrap();
    assert_eq!(res.status(), StatusCode::NOT_FOUND);
}
EOF
